static void activate_foreach_backend(uint32_t *mask)
{
	for (int backend_id = 0; backend_id < log_backend_count_get(); backend_id++) {
		const struct log_backend *backend = log_backend_get(backend_id);

		if (!backend_activate(backend, mask, backend_id)) {
			break;
		}
	}
}

static void z_log_init(bool blocking, bool can_sleep)
{
	uint32_t mask = 0U;
	int backend_id = 0;

	if (IS_ENABLED(CONFIG_LOG_FRONTEND_ONLY)) {
		return;
	}

	for (backend_id = 0; backend_id < log_backend_count_get(); backend_id++) {
		const struct log_backend *backend = log_backend_get(backend_id);

		if (backend->autostart) {
			log_backend_id_set(backend, backend_id);
			backend->cb->ctx = NULL;
			log_backend_init(backend);

			if (log_backend_is_ready(backend) == 0) {
				log_backend_enable(backend, backend->cb->ctx, CONFIG_LOG_MAX_LEVEL);
			} else {
				mask |= BIT(backend_id);
			}
		}
	}

	atomic_set(&autostart_pending_mask, mask);

	while (blocking && mask != 0U) {
		if (can_sleep) {
			k_sleep(K_MSEC(50));
		}

		activate_foreach_backend(&mask);
		atomic_set(&autostart_pending_mask, mask);
	}
}

